import{_ as e,o as n,c as a,a as r}from"./app.9d668088.js";var t="/aktivitaeten/Eyeball-QSO-Villmar-2026-08-22/01-antennenaufbau.jpg",s="/aktivitaeten/Eyeball-QSO-Villmar-2026-08-22/02-erste-verbindung.jpg",i="/aktivitaeten/Eyeball-QSO-Villmar-2026-08-22/03-camp-aufbau.jpg",l="/aktivitaeten/Eyeball-QSO-Villmar-2026-08-22/06-zwei-ops-antenne.jpg",u="/aktivitaeten/Eyeball-QSO-Villmar-2026-08-22/04-sturmwolken-ziehen-auf.jpg",h="/aktivitaeten/Eyeball-QSO-Villmar-2026-08-22/10-schutz-im-auto.jpg",d="/aktivitaeten/Eyeball-QSO-Villmar-2026-08-22/11-regen-scheibe.jpg",g="/aktivitaeten/Eyeball-QSO-Villmar-2026-08-22/08-gespraech-nach-regen.jpg",o="/aktivitaeten/Eyeball-QSO-Villmar-2026-08-22/09-funkbetrieb-nachmittag.jpg",m="/aktivitaeten/Eyeball-QSO-Villmar-2026-08-22/05-camp-uebersicht.jpg",c="/aktivitaeten/Eyeball-QSO-Villmar-2026-08-22/07-gruppenfoto.jpg",p="/aktivitaeten/Eyeball-QSO-Villmar-2026-08-22/12-logbuch-pflege.jpg";const b={},f=r('<h1 id="erbarme-\u2013-zu-spat-die-draussenfunker-hessen-kommen" tabindex="-1"><a class="header-anchor" href="#erbarme-\u2013-zu-spat-die-draussenfunker-hessen-kommen" aria-hidden="true">#</a> Erbarme \u2013 zu sp\xE4t! Die Draussenfunker Hessen kommen!</h1><h3 id="ruckblick-1-draussenfunker-hessen-eyeball-qso-\u2013-22-august-2026-\u2013-wanderparkplatz-galgenberg-villmar" tabindex="-1"><a class="header-anchor" href="#ruckblick-1-draussenfunker-hessen-eyeball-qso-\u2013-22-august-2026-\u2013-wanderparkplatz-galgenberg-villmar" aria-hidden="true">#</a> R\xFCckblick: 1. Draussenfunker Hessen Eyeball QSO \u2013 22. August 2026 \u2013 Wanderparkplatz Galgenberg, Villmar</h3><hr><p>Es war mal wieder Zeit, den \xC4ther mit Antennen zu bev\xF6lkern \u2013 diesmal aber nicht alleine und nicht von zuhause aus, sondern <strong>von Angesicht zu Angesicht, drau\xDFen, in der freien hessischen Natur</strong>. Das erste Draussenfunker Hessen Eyeball QSO war anberaumt. Der Wanderparkplatz Galgenberg in Villmar hatte keine Ahnung, was auf ihn zukam.</p><p>Tomas (DB4SNK) hatte die Location empfohlen \u2013 und er hatte nicht zu viel versprochen: Viel Platz, gro\xDFe Freifl\xE4chen direkt am Parkplatz, eine kleine H\xFCtte f\xFCr Notf\xE4lle (Spoiler: die H\xFCtte wurde gebraucht) und eine Aussicht, die das Herz jedes Draussenfunkers h\xF6her schlagen l\xE4sst. Kurz gesagt: <strong>perfekt.</strong></p><hr><h2 id="die-crew-ist-da-\u2013-von-dreieich-bis-in-den-taunus" tabindex="-1"><a class="header-anchor" href="#die-crew-ist-da-\u2013-von-dreieich-bis-in-den-taunus" aria-hidden="true">#</a> Die Crew ist da \u2013 von Dreieich bis in den Taunus</h2><p>Insgesamt <strong>8 OPs</strong> aus ganz Hessen hatten sich auf den Weg gemacht \u2013 von Miltenberg (lassen wir noch als Hessen gelten) \xFCber die Wetterau, Mittelhessen bis in den Taunus. Wer sagt, Funkamateure k\xE4men nicht aus dem Haus?</p><p><strong>Anwesende OPs:</strong></p><ul><li><strong>DA6XJ</strong> \u2013 Kai</li><li><strong>DN9GU</strong> \u2013 Andreas</li><li><strong>DA6MAX</strong> \u2013 Max</li><li><strong>DB4SNK</strong> \u2013 Tomas <em>(der mit der guten Ortskenntnis)</em></li><li><strong>DL1AMG</strong> \u2013 Paolo</li><li><strong>DB4SCW</strong> \u2013 Stefan</li><li><strong>DO1DX</strong> \u2013 Daniel</li><li><strong>DA6MIA</strong> \u2013 Mona</li></ul><p>Vom Newcomer bis zum erfahrenen Portabelfunker war alles vertreten. Die Antennen wurden ausgepackt, die TRX aufgebaut und schon ging das Fachsimpeln los \u2013 bevor \xFCberhaupt eine einzige Taste gedr\xFCckt wurde. Typisch Funkamateure. \u{1F604}</p><p><img src="'+t+'" alt="Antennenaufbau am Galgenberg"><img src="'+s+'" alt="Erste Verbindungen im Log"></p><hr><h2 id="antennen-raus-bander-offen-\u2013-und-10m-war-der-star-des-tages" tabindex="-1"><a class="header-anchor" href="#antennen-raus-bander-offen-\u2013-und-10m-war-der-star-des-tages" aria-hidden="true">#</a> Antennen raus, B\xE4nder offen \u2013 und 10m war der Star des Tages!</h2><p>Die Parks standen bereit f\xFCr die Aktivierung:</p><ul><li>\u{1F332} <strong>DE-0601</strong> \u2013 Jakobswege Lahn-Mosel-Eifel-Rhein National Historic Trail (DE-HE)</li><li>\u{1F332} <strong>DE-0034</strong> \u2013 Taunus Nature Park (DE-HE)</li></ul><p>Wer einen seltenen <strong>2fer</strong> aktivieren wollte, war hier genau richtig.</p><p>Das Wetter spielte zun\xE4chst perfekt mit \u2013 nicht zu warm, nicht zu kalt, leichte Bew\xF6lkung. Ideale Bedingungen. Die ersten QSOs wanderten in den Log, die Antennen strahlten in alle Richtungen und dann passierte es: <strong>10m war offen. Richtig offen.</strong> Die OPs, die auf HF gesetzt hatten, strahlten fast so sehr wie ihre Antennen. DX kam rein, Pile-Ups entstanden und f\xFCr einen kurzen Moment verga\xDF man sogar, dass man eigentlich zum gemeinsamen Grillen gekommen war.</p><p><img src="'+i+'" alt="Camp-Aufbau am Parkplatz"><img src="'+l+'" alt="Zwei OPs bei der Antennenkontrolle"></p><hr><h2 id="feucht-frohlich-als-der-regen-die-regie-ubernahm" tabindex="-1"><a class="header-anchor" href="#feucht-frohlich-als-der-regen-die-regie-ubernahm" aria-hidden="true">#</a> Feucht-fr\xF6hlich: Als der Regen die Regie \xFCbernahm</h2><p>Und dann \u2013 wie es bei Draussenfunkern eben manchmal so l\xE4uft \u2013 <strong>zog der Regen auf.</strong> Nicht irgendein kleines Tr\xF6pfchen, sondern die Sorte Regen, bei der man innerhalb von Sekunden beschlie\xDFt, die Lieblingsausr\xFCstung zu retten.</p><p><img src="'+u+'" alt="Die Sturmwolken ziehen auf"></p><p>TRX rein, Kabel schnell aufgerollt, Antennen gesichert \u2013 und dann: <strong>20 Minuten Schutz in den Autos.</strong> Aber aufgeh\xF6rt haben die Draussenfunker Hessen nat\xFCrlich nicht! Wer glaubt, ein bisschen Regen stoppt hessische Funkamateure, der irrt sich gewaltig. Kurzerhand wurde auf <strong>2m und 70cm</strong> weitergemacht \u2013 flei\xDFig durch die Autoscheibe aktiviert, w\xE4hrend der Regen auf das Dach trommelte. Das nennt man Pragmatismus. Oder Sturheit. Je nach Perspektive. \u{1F604}</p><p><img src="'+h+'" alt="Schutz im Auto"><img src="'+d+'" alt="Regen auf der Windschutzscheibe"></p><hr><h2 id="die-sonne-kommt-zuruck-\u2013-und-mit-ihr-die-wurstchen" tabindex="-1"><a class="header-anchor" href="#die-sonne-kommt-zuruck-\u2013-und-mit-ihr-die-wurstchen" aria-hidden="true">#</a> Die Sonne kommt zur\xFCck \u2013 und mit ihr die W\xFCrstchen!</h2><p>Kaum hatte der Regen nachgelassen, waren auch schon wieder alle drau\xDFen. Antennen raus, Ger\xE4te ans Netz \u2013 und der <strong>Grill angeworfen!</strong> W\xFCrstchen brutzeln, w\xE4hrend im Hintergrund die Pile-Ups weiterlaufen \u2013 so muss das sein.</p><p>Die meisten OPs konnten am Ende die <strong>Aktivierung beider Parks mitnehmen</strong> \u2013 der begehrte 2fer war f\xFCr viele in der Tasche. Mission accomplished!</p><p><img src="'+g+'" alt="Gespr\xE4che nach dem Regen"><img src="'+o+'" alt="Funkbetrieb am Nachmittag"><img src="'+m+'" alt="\xDCbersicht \xFCber das Camp"></p><hr><h2 id="fazit-ein-erster-eyeball-qso-der-lust-auf-mehr-macht" tabindex="-1"><a class="header-anchor" href="#fazit-ein-erster-eyeball-qso-der-lust-auf-mehr-macht" aria-hidden="true">#</a> Fazit: Ein erster Eyeball QSO, der Lust auf mehr macht</h2><p>Was soll man sagen? Es war ein <strong>toller Tag.</strong> Tolle Menschen, tolle Gespr\xE4che, tolle B\xE4nder \u2013 und ein Regen, der uns nur kurz, aber nicht wirklich aufgehalten hat. Genau das ist es, was Draussenfunken ausmacht: drau\xDFen sein, miteinander funken, gemeinsam lachen \u2013 auch wenn der Himmel mal nicht mitspielt.</p><p><img src="'+c+'" alt="Gruppenfoto der Draussenfunker Hessen"></p><p>Ein riesiges <strong>Danke</strong> an Tomas (DB4SNK) f\xFCr die fantastische Locationempfehlung, an alle OPs die den Weg nach Villmar gefunden haben und nat\xFCrlich an das Wetter \u2013 f\xFCr den dramatischen Einwurf in der Mitte, der dem Ganzen noch eine gewisse Epik verliehen hat. \u{1F327}\uFE0F\u{1F4FB}</p><p><img src="'+p+'" alt="Logbuch-Pflege zum Abschluss"></p><p>Das erste Hessische Draussenfunker Eyeball QSO ist Geschichte. Und das n\xE4chste kommt bestimmt \u2013 <strong>Herbst in Karben, Save the Date!</strong></p><p>Erbarme? Keine Chance. Die Draussenfunker Hessen kommen wieder.</p><hr><p><em>73, Max (DA6MAX) &amp; Tomas (DB4SNK)</em><em>im Namen aller Draussenfunker Hessen</em></p>',40),k=[f];function w(v,D){return n(),a("div",null,k)}var _=e(b,[["render",w],["__file","2026-08-22-Draussenfunker-Hessen-Eyeball-QSO-Villmar.html.vue"]]);export{_ as default};
